"""Tests for tasks_api.queries — TaskQuery, apply_query, TaskPage."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(
    id: int,
    title: str = "task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at=None,
    tags=None,
    created_at=None,
):
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        tags=tags or [],
        created_at=created_at or NOW,
    )


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "unknown", ""])
    def test_invalid_sort_field(self, bad_sort):
        with pytest.raises(TaskQueryError):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "abc"])
    def test_invalid_limit(self, bad_limit):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=bad_limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_normalization(self):
        q = TaskQuery(tag="  Hello  ")
        assert q.tag == "hello"

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_strips(self):
        q = TaskQuery(search="  buy  ")
        assert q.search == "buy"


# ── TaskPage ─────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1), _task(2)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(1)], total=3, limit=2, offset=2)
        assert page.has_more is False

    def test_has_more_exact_fit(self):
        page = TaskPage(items=[_task(1), _task(2)], total=2, limit=2, offset=0)
        assert page.has_more is False


# ── apply_query: filtering ───────────────────────────────────────────

class TestApplyQueryFilters:
    @pytest.fixture
    def tasks(self):
        past = NOW - timedelta(days=5)
        future = NOW + timedelta(days=5)
        return [
            _task(1, "Buy milk", TaskStatus.PENDING, TaskPriority.LOW, due_at=past, tags=[Tag("grocery")]),
            _task(2, "Write report", TaskStatus.DONE, TaskPriority.HIGH, created_at=NOW - timedelta(hours=1)),
            _task(3, "Read book", TaskStatus.PENDING, TaskPriority.MEDIUM, due_at=future, tags=[Tag("personal")]),
            _task(4, "Buy eggs", TaskStatus.PENDING, TaskPriority.LOW, due_at=past),
        ]

    def test_no_filters_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert page.total == 3
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="grocery"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # Task 2 (done) is not overdue, Task 3 (future) is not overdue
        assert all(not t.is_overdue(NOW) for t in page.items)

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, search="buy", overdue=True), NOW)
        assert page.total == 2


# ── apply_query: sorting ─────────────────────────────────────────────

class TestApplyQuerySort:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Charlie", priority=TaskPriority.LOW, created_at=NOW - timedelta(hours=3)),
            _task(2, "Alpha", priority=TaskPriority.HIGH, created_at=NOW - timedelta(hours=1)),
            _task(3, "Bravo", priority=TaskPriority.MEDIUM, created_at=NOW - timedelta(hours=2)),
        ]

    def test_sort_by_title_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Alpha", "Bravo", "Charlie"]

    def test_sort_by_title_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Charlie", "Bravo", "Alpha"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH,
            TaskPriority.MEDIUM,
            TaskPriority.LOW,
        ]

    def test_sort_by_created_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 3, 2]

    def test_sort_by_due_at_with_nones(self):
        future1 = NOW + timedelta(days=1)
        future2 = NOW + timedelta(days=3)
        tasks = [
            _task(1, "no-due"),
            _task(2, "soon", due_at=future1),
            _task(3, "later", due_at=future2),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # None due_at sorts last in ascending
        assert [t.id for t in page.items] == [2, 3, 1]


# ── apply_query: pagination ──────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, f"task-{i}") for i in range(1, 8)]  # 7 tasks

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 7
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=5), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=10), NOW)
        assert len(page.items) == 0
        assert page.total == 7
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository + normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    @pytest.fixture
    def task(self):
        return Task(id=1, title="Test task")

    def test_add_and_get(self, repo, task):
        repo.add(task)
        fetched = repo.get(task.id)
        assert fetched is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_id_raises(self, repo, task):
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(task)

    def test_list_returns_snapshot(self, repo):
        t1 = Task(id=1, title="A")
        t2 = Task(id=2, title="B")
        repo.add(t1)
        repo.add(t2)
        result = repo.list()
        assert len(list(result)) == 2

    def test_update_existing(self, repo, task):
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(Task(id=999, title="missing"))

    def test_delete_existing(self, repo, task):
        repo.add(task)
        assert repo.delete(task.id) is True
        assert repo.get(task.id) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(42) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_strings_converted_to_tags(self):
        result = normalize_tags(["hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_tag_instances_passed_through(self):
        tags = [Tag("a"), Tag("b")]
        result = normalize_tags(tags)
        assert [t.name for t in result] == ["a", "b"]

    def test_deduplication_preserves_order(self):
        result = normalize_tags(["foo", "bar", "FOO", "Bar"])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_mixed_types(self):
        result = normalize_tags([Tag("x"), "X", "y"])
        assert [t.name for t in result] == ["x", "y"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

