        repo.add(task)
        assert repo.delete(task.id) is True
        assert repo.get(task.id) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(42) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_strings_converted_to_tags(self):
        result = normalize_tags(["hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_tag_instances_passed_through(self):
        tags = [Tag("a"), Tag("b")]
        result = normalize_tags(tags)
        assert [t.name for t in result] == ["a", "b"]

    def test_deduplication_preserves_order(self):
        result = normalize_tags(["foo", "bar", "FOO", "Bar"])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_mixed_types(self):
        result = normalize_tags([Tag("x"), "X", "y"])
        assert [t.name for t in result] == ["x", "y"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

